"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0db/refs"
import { cn } from "@/lib/utils"

type StrataProps = React.ComponentProps<"div"> & { trigger?: "scroll" | "load" }
type StrataPlaneProps = React.ComponentProps<"div"> & {
  depth: number
  tilt?: "x" | "y" | "none"
  from?: "start" | "end" | "above" | "below"
}

/** Depth means a thought not yet set. Its reading order never changes as the planes come forward. */
function Strata({ trigger = "scroll", children, className, ref: forwardedRef, ...props }: StrataProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const composedRef = useComposedRefs(ref, forwardedRef)
  const played = React.useRef(false)

  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    const planes = Array.from(el.querySelectorAll<HTMLElement>(":scope > .db-strata-plane"))
    const ordered = [...planes].sort((a, b) => Number(b.dataset.depth) - Number(a.dataset.depth))
    ordered.forEach((plane, i) => plane.style.setProperty("--db-strata-order", String(i)))
    el.style.setProperty("--db-strata-count", String(Math.max(1, planes.length)))
    const still = matchMedia("(prefers-reduced-motion: reduce)")
    const native = CSS.supports("animation-timeline", "view()")
    let frame = 0
    const set = (p: number) => el.style.setProperty("--p", String(p))
    function read() {
      frame = 0
      if (still.matches) return set(1)
      const box = el!.getBoundingClientRect(), top = box.top + scrollY
      const from = Math.max(0, top - innerHeight)
      const to = Math.min(document.documentElement.scrollHeight - innerHeight, top - innerHeight + (innerHeight + box.height) * 0.65)
      set(to <= from ? 1 : Math.max(0, Math.min(1, (scrollY - from) / (to - from))))
    }
    function scroll() { if (!frame) frame = requestAnimationFrame(read) }
    function configure() {
      cancelAnimationFrame(frame); frame = 0
      if (still.matches) {
        el!.removeAttribute("data-ready")
        set(1)
        played.current = true
      } else if (trigger === "load") {
        // Toggling reduced motion off must not replay an opening already read.
        if (!played.current) { el!.dataset.ready = "load"; played.current = true }
      } else if (native) { el!.dataset.ready = "scroll"; el!.style.removeProperty("--p") }
      else { el!.dataset.ready = "fallback"; read() }
    }
    frame = requestAnimationFrame(configure)
    if (trigger === "scroll" && !native) {
      addEventListener("scroll", scroll, { passive: true })
      addEventListener("resize", scroll)
    }
    still.addEventListener("change", configure)
    return () => {
      cancelAnimationFrame(frame)
      removeEventListener("scroll", scroll)
      removeEventListener("resize", scroll)
      still.removeEventListener("change", configure)
      el.removeAttribute("data-ready")
      el.style.removeProperty("--p")
    }
  }, [trigger, children])

  return <div ref={composedRef} data-slot="strata" data-trigger={trigger} className={cn("db-strata", className)} {...props}>{children}</div>
}

function StrataPlane({ depth, tilt = "y", from = "start", className, style, ...props }: StrataPlaneProps) {
  const distance = Number.isFinite(depth) ? Math.max(0, Math.min(1, depth)) : 0
  return <div data-slot="strata-plane" data-depth={distance} data-tilt={tilt} data-from={from} className={cn("db-strata-plane", className)} style={{ ...style, "--db-strata-depth": distance } as React.CSSProperties} {...props} />
}

export { Strata, StrataPlane, type StrataProps, type StrataPlaneProps }

@property --db-strata-progress { syntax: "<number>"; inherits: true; initial-value: 1; }
@layer components {
  /* WOVE brings the chosen words near; here the angle falls away until the thought is clear. */
  .db-strata { --db-strata-count: 1; --db-strata-reach: 1; --db-strata-direction: 1; perspective: 60rem; display: grid; gap: var(--db-space-5); }
  .db-strata-plane :where(h1, h2, h3, h4, h5, h6) { color: inherit; }
  .db-strata-plane { --db-strata-depth: 0; --db-strata-order: 0; min-inline-size: 0; color: var(--db-ink); transform-origin: center; }
  .db-strata[data-ready] > .db-strata-plane {
    --db-strata-step: 0.025714; /* one arpeggio / adagio: 36 / 1400 */
    --db-strata-at: clamp(0, calc((var(--p, var(--db-strata-progress)) - var(--db-strata-order) * var(--db-strata-step)) / max(0.1, 1 - (var(--db-strata-count) - 1) * var(--db-strata-step))), 1);
    --db-strata-away: calc((1 - var(--db-strata-at)) * var(--db-strata-depth) * var(--db-strata-reach));
    --db-strata-x: 0;
    --db-strata-y: 0;
    --db-strata-rx: 0;
    --db-strata-ry: 0;
    transform: translate3d(calc(var(--db-strata-x) * var(--db-strata-away) * var(--db-space-8)), calc(var(--db-strata-y) * var(--db-strata-away) * var(--db-space-8)), calc(var(--db-strata-away) * -24rem)) rotateX(calc(var(--db-strata-rx) * var(--db-strata-away) * 28deg)) rotateY(calc(var(--db-strata-ry) * var(--db-strata-away) * 28deg)) scale(calc(1 - var(--db-strata-away) * 0.22));
    color: color-mix(in oklab, var(--db-ink) calc(var(--db-strata-at) * 100%), var(--db-pencil));
  }
  .db-strata[data-ready] > .db-strata-plane[data-from="start"] { --db-strata-x: calc(-1 * var(--db-strata-direction)); }
  .db-strata[data-ready] > .db-strata-plane[data-from="end"] { --db-strata-x: var(--db-strata-direction); }
  .db-strata[data-ready] > .db-strata-plane[data-from="above"] { --db-strata-y: -1; }
  .db-strata[data-ready] > .db-strata-plane[data-from="below"] { --db-strata-y: 1; }
  .db-strata[data-ready] > .db-strata-plane[data-tilt="x"] { --db-strata-rx: 1; }
  .db-strata[data-ready] > .db-strata-plane[data-tilt="y"] { --db-strata-ry: var(--db-strata-direction); }
  :is([dir="rtl"], [dir="rtl"] *) .db-strata { --db-strata-direction: -1; }
  .db-strata[data-ready="load"] > .db-strata-plane {
    --db-strata-at: var(--db-strata-progress);
    animation: db-strata-arrive var(--db-adagio) var(--db-exhale) both;
    animation-delay: calc(var(--db-strata-order) * var(--db-arpeggio));
  }
  @supports (animation-timeline: view()) {
    .db-strata[data-ready="scroll"] { animation-name: db-strata-arrive; animation-timing-function: linear; animation-fill-mode: both; animation-timeline: view(); animation-range: entry 0% cover 65%; } /* longhands: the CSS build drops the shorthand beside a timeline */
  }
  @keyframes db-strata-arrive { from { --db-strata-progress: 0; } to { --db-strata-progress: 1; } }
  @media (max-width: 40rem) { .db-strata { --db-strata-count: 1; --db-strata-reach: 0.4; } }
  @media (prefers-reduced-motion: reduce) {
    .db-strata[data-ready], .db-strata[data-ready] > .db-strata-plane { animation: none; }
    .db-strata[data-ready] > .db-strata-plane { transform: none; color: var(--db-ink); }
  }
  @media (forced-colors: active) { .db-strata-plane, .db-strata[data-ready] > .db-strata-plane { color: CanvasText; } }
}
